#!/usr/bin/env python3

"""This script scans a compilation database and executes clang-tidy
   with the specified configuration file against all files from the
   database, using a configurable number of workers to speed things up.
   The fixes generated by clang-tidy are written to YAML files. They
   can later be turned into SAST reports in markdown and YAML formats using
   clang-tidy-fixes-to-sast-report.py.
"""

import argparse
import os
import sys
import yaml
from pathlib import Path

import helpers

def create_argument_parser():
    """Create command-line argument parser."""
    parser = argparse.ArgumentParser(description="Run clang-tidy against the files found in a compilation database")
    parser.add_argument(
        "--database",
        type=str,
        required=True,
        default="",
        help="Path to the directory where the compile_commands.json database can be found",
    )
    parser.add_argument(
        "--fixes-files-dir",
        type=str,
        required=True,
        help="Path to the directory where the clang-tidy fixes YAML files will be written (one per worker)",
    )
    parser.add_argument(
        "--workers",
        type=int,
        required=False,
        default=1,
        help="The number of concurrent clang-tidy workers to execute",
    )
    return parser.parse_args()


def main():
    """Start the script."""
    args = create_argument_parser()

    compdb_path = os.path.join(args.database, "compile_commands.json")
    compdb = helpers.load_compdb(compdb_path)
    compdb = helpers.index_compdb(compdb)



    return 0

if __name__ == "__main__":
    sys.exit(main())
